import appLogger from '../utils/logger/app-logger.ts';

class Configuration {
  public getClientId(): string {
    const clientId = import.meta.env.IDENTITY_PROVIDER_APP_CLIENT_ID;
    if (!clientId) {
      throw new Error('CLIENT_ID not found in environment variables.');
    }
    appLogger.debug(this);
    return clientId;
  }

  public getAuthority(): string {
    const authority = import.meta.env.IDENTITY_PROVIDER_APP_AUTHORITY;
    if (!authority) {
      throw new Error('AUTHORITY not found in environment variables.');
    }
    appLogger.debug(this);
    return authority;
  }

  public getRedirectUri(): string {
    const redirectUri = import.meta.env.APP_REDIRECT_URI;
    if (!redirectUri) {
      throw new Error('REDIRECT_URI not found in environment variables.');
    }
    appLogger.debug(this);
    return redirectUri;
  }

  public getScopes(): string {
    const scopes = import.meta.env.IDENTITY_PROVIDER_APP_SCOPES;
    if (!scopes) {
      throw new Error('SCOPES not found in environment variables.');
    }
    appLogger.debug(this);
    return scopes;
  }

  public getResponseType(): string {
    appLogger.debug(this);
    const code = import.meta.env.IDENTITY_PROVIDER_APP_RESPONSE_TYPE;
    return code;
  }

  public getAccessTokenExpiringNotificationTime(): number {
    appLogger.debug(this);
    const value =
      import.meta.env.ACCESS_TOKEN_EXPIRING_REFRESH_SECONDS || '1800';
    return Number.parseInt(value, 10);
  }
}

const configuration = new Configuration();

export { configuration };

import axios, { AxiosResponse } from 'axios';
import { UserProfile } from '../types/user-profile.dto';

const umeBackend = import.meta.env.URL_UME_BACKEND;
const token = import.meta.env.TOKEN;
interface Claim {
  typ: string;
  val: string | Array<string>;
}

interface DecodedPrincipal {
  authType: string;
  claims: Array<Claim>;
}

export interface User {
  profile: UserProfile;
  lastLogin: Date;
}

const extractGroupNames = async (
  rawGroups: Array<string>,
): Promise<Array<string>> => {
  const regex = /CN=([^,]+)/;
  return rawGroups.map((group) => {
    const match = regex.exec(group);
    return match ? match[1] : group;
  });
};

export const getUser = async (): Promise<User | undefined> => {
  try {
    const response: AxiosResponse<DecodedPrincipal> = await axios.get(
      `${umeBackend}/auth/claims`,
      {
        headers: {
          authorization: `Bearer ${token}`,
        },
        withCredentials: true,
      },
    );

    const claims = response.data?.claims ?? [];

    const getClaim = (suffix: string): string | undefined =>
      claims.find((c) => c.typ.toLowerCase().endsWith(suffix.toLowerCase()))
        ?.val as string;

    const getGroupClaims = (): Array<string> => {
      return claims
        .filter((c) => c.typ.toLowerCase().endsWith('groups'))
        .flatMap((c) => {
          if (Array.isArray(c.val))
            return c.val.filter((v): v is string => typeof v === 'string');
          return typeof c.val === 'string' ? [c.val] : [];
        });
    };

    const email = getClaim('emailaddress') ?? '';
    const givenName = getClaim('givenname') ?? '';
    const familyName = getClaim('surname') ?? '';
    const groupRaw = getGroupClaims();
    const groups = await extractGroupNames(groupRaw);
    const profile = new UserProfile(email, givenName, familyName, groups);
    return {
      profile,
      lastLogin: new Date(),
    };
  } catch (error) {
    console.error('Failed to fetch user claims:', error);
    return undefined;
  }
};

