import { createI18n, I18n } from 'vue-i18n';
import ar from './locales/ar.json';
import cz from './locales/cz.json';
import en from './locales/en.json';
import es from './locales/es-ES.json';
import esMX from './locales/es-MX.json';
import fr from './locales/fr.json';
import pl from './locales/pl.json';
import ptBR from './locales/pt-BR.json';
import pt from './locales/pt-PT.json';
import sk from './locales/sk.json';
import zh from './locales/zh-CN.json';
import zhHK from './locales/zh-HK.json';

/**
 * Setup the i18n instance with the selected locale and available messages.
 * @returns A promise that resolves to the i18n instance.
 */
export async function setupI18n(): Promise<I18n> {
  // Const localeStore = useLocaleStore();
  // Await localeStore.setLocale();
  const messages: Record<string, any> = {
    ar,
    cz,
    en,
    es,
    esMX,
    fr,
    pl,
    pt,
    ptBR,
    sk,
    zh,
    zhHK,
  };
  return createI18n({
    locale: 'en',
    fallbackLocale: 'en',
    messages,
  });
}

import mainHeader, { NotifyPlugin } from '@mesx/common-ui-lib';
import { createPinia } from 'pinia';
import piniaPluginPersistedstate from 'pinia-plugin-persistedstate';
import { Quasar } from 'quasar';
import { createApp } from 'vue';
import App from './App.vue';
import { setupI18n } from './localization/i18n.ts';
import ganttastic from './modules/leveling-board/components/Gantt/vue-ganttastic.ts';
import quasarConfig from './quasar-user-options.ts';
import { router } from './router/index.ts';
import './data.ts';
import '@mesx/common-ui-lib/style.css';

/**
 *
 */
async function initializeApp(): Promise<void> {
  const pinia = createPinia();
  const app = createApp(App);

  app.use(Quasar, quasarConfig);
  app.use(pinia);
  pinia.use(piniaPluginPersistedstate);
  app.use(router);
  app.use(ganttastic);
  app.use(mainHeader);
  const { $q } = app.config.globalProperties;

  app.use(NotifyPlugin, { $q });

  try {
    const i18n = await setupI18n();
    app.use(i18n);
  } catch (error) {
    console.error('Failed to initialize i18n:', error);
  }

  app.mount('#app');
}

