/**
 * Cleans up expired or corrupted redirect sessions from localStorage.
 *
 * A redirect session is considered expired if its `expiresAt` timestamp
 * is less than the current time.
 *
 * This function should be called periodically (e.g. on app startup)
 * to prevent accumulation of stale sessions.
 * @example
 * cleanupRedirectSessions();
 * // Removes all expired redirectSession_* entries from localStorage
 */
function cleanupRedirectSessions(): void {
  const now = Date.now();

  for (const key of Object.keys(localStorage)) {
    if (key.startsWith('redirectSession_')) {
      try {
        const payload = JSON.parse(localStorage.getItem(key) as string);
        if (!payload || payload.expiresAt < now) {
          localStorage.removeItem(key);
        }
      } catch {
        localStorage.removeItem(key); // Corrupted → delete
      }
    }
  }
}

/**
 * Creates a new redirect session in localStorage.
 *
 * The session key will be prefixed with `redirectSession_` followed by a unique UUID.
 * The value stored is a JSON string containing:
 * - `data`: arbitrary details you want to share between apps
 * - `expiresAt`: expiration timestamp in milliseconds since epoch
 * @param data - The data object to persist in the session (must be JSON-serializable).
 * @returns The generated session key (e.g. "redirectSession_123abc").
 * @example
 * const key = createRedirectSession({ filters: { status: 'open' } });
 * // -> "redirectSession_abcd-1234..."
 * // Then pass this key (or just the UUID part) to App2 via URL
 */
function createRedirectSession(data: unknown): string {
  const sessionId = crypto.randomUUID();
  const createdAt = Date.now();
  const expiresAt = createdAt + 5 * 60 * 1000; // 5 minutes from now
  const redirectSession = `redirectSession_${sessionId}`;
  cleanupRedirectSessions();

  const payload = {
    createdAt,
    data,
    expiresAt,
  };

  localStorage.setItem(redirectSession, JSON.stringify(payload));
  return redirectSession;
}

/**
 * Recursively extracts all values of a given property name
 * from an object of arbitrary structure.
 * @param object - The object to search through.
 * @param propertyName - The property name to extract values for.
 * @returns An array of values found for the property.
 * @example
 * const json = '{"foo":{"bar":[{"shopOrder":"ORDER_1"},{"shopOrder":"ORDER_2"}]}}';
 * const data = JSON.parse(json);
 * const orders = extractValues(data, "shopOrder");
 * console.log(orders); // ["ORDER_1", "ORDER_2"]
 */
function extractValues(object: unknown, propertyName: string): Array<string> {
  const results: Array<string> = [];
  /**
   * Helper function to recursively traverse arrays/objects.
   * @param value - Current value being traversed.
   */
  function recurse(value: unknown): void {
    if (Array.isArray(value)) {
      for (const item of value) {
        recurse(item);
      }
    } else if (value && typeof value === 'object') {
      for (const [key, innerValue] of Object.entries(value)) {
        if (key === propertyName) {
          results.push(innerValue as string);
        }
        recurse(innerValue);
      }
    }
  }

  recurse(object);
  return results;
}

export { createRedirectSession, extractValues };

