const appRedirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string | undefined;
if (appRedirectUri) {
  const parts = appRedirectUri.split('/');
  appBasePath = parts.pop();
}
const appName = 'LEVELING-BOARD';
const routes = [
  {
    component: LevelingTimlineBoard,
    meta: { appName, requiresAuth: true, title: 'Leveling timeline Board' },
    name: 'LevelingTimlineBoard',
    path: '/lvl-ui',
    props: true,
  },
  {
    component: LevelingTimlineBoard,
    meta: { appName, requiresAuth: true, title: 'Leveling timeline Board' },
    name: 'SharedGroupFilterBoard',
    path: '/lvl-ui/:groupName',
    props: true,
  },
  {
    component: advancedFilter,
    meta: { appName, requiresAuth: true, title: 'Filter Layout' },
    name: 'Filter Layout',
    path: '/lvl-ui/filter-layout',
    props: true,
  },
  {
    component: LevelTimelineScndVersion,
    meta: { appName, requiresAuth: true, title: 'Leveling vis timeline Board' },
    name: 'LevelTimelineScndVersion',
    path: '/lvl-ui-timeline-v2/',
    props: true,
  },
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
        router.push('/lvl-ui');
      },
    },
  },
  {
    component: Unauthorized,
    name: 'Unauthorized',
    path: `/${appBasePath}/unauthorized`,
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: `/${appBasePath}/loading`,
  },
];
export const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  const userAuth = useProfileStore();
  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      } else {
        // Handle the case where the user is null
        console.error('User not found');
        return next(`/${appBasePath}/unauthorized`); // Return is added here
      }

      // Proceed to the route
      return next(); // Explicit return added
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next(`/${appBasePath}/unauthorized`); // Return is added here
    }
  } else {
    return next(); // Explicit return for non-authenticated routes
  }
});

