export const apiService = {
  async getWorkcenterDetailsById(
    plantId: number,
    workcenterId: string,
  ): Promise<WorkcenterDetails> {
    try {
      const apiUrl = `${API_BASE_URL}/wk/getWorkcenterDetails/${plantId}/${workcenterId}`;
      const headers = token ? { authorization: `Bearer ${token}` } : {};
      const response = await axios.get(apiUrl, {
        withCredentials: true,
        headers,
      });
      return response.data;
    } catch (error: unknown) {
      console.error('Error fetching workcenter details:', error);
      if (typeof error === 'object' && error !== null && 'response' in error) {
        throw new Error(
          `HTTP error! Status: ${(error as { response: { status: number } }).response.status},`,
        );
      } else if (
        typeof error === 'object' &&
        error !== null &&
        'request' in error
      ) {
        throw new Error('No response received from the server.');
      } else {
        throw new Error(`Error in request setup: ${(error as Error).message}`);
      }
    }
  },
  async getWorkOrder(
    plant: number,
    startDate: string,
    endDate: string,
    queryParameters?: {
      closedWKs?: boolean;
      customer?: string;
      workCenter?: string;
      uap?: string;
      pickingOrder?: string;
      outboundDelivery?: string;
      material?: string;
      destinationTypeList?: string;
      customStatusList?: string;
      sourceTypeList?: string;
      tpaNumberList?: string;
      filterGroupingOne?: string;
      filterGroupingTwo?: string;
      startPreparationLabel?: string;
      customStartPreparationDate?: string;
      truckDepartureLabel?: string;
      customTruckDepartureDate?: string;
      pickingStatusList?: Array<string>;
    },
  ): Promise<PlantResponse> {
    try {
      let apiUrl = `${API_BASE_URL}/wk/getWkOrderByCriteria/${plant}`;
      const parameter = queryParameters ?? {};

      const queryString = this.buildQueryString(parameter);

      if (queryString) {
        apiUrl += `?${queryString}`;
      }

      const parameters: object = {
        startDate,
        endDate,
      };

      const response = await axios.get(apiUrl, {
        params: parameters,
        withCredentials: true,
        headers: token ? { authorization: `Bearer ${token}` } : {},
      });

      return response.data;
    } catch (error: any) {
      console.error('Error fetching work order:', error);

      if (error.response) {
        throw new Error(`HTTP error! Status: ${error.response.status}`);
      } else if (error.request) {
        throw new Error('No response received from the server.');
      } else {
        throw new Error(`Error in request setup: ${error.message}`);
      }
    }
  },

  buildQueryString(parameters: QueryParameters): string {
    const queryStrings = [];
    const {
      closedWKs,
      customer,
      workCenter,
      uap,
      pickingOrder,
      outboundDelivery,
      material,
      destinationTypeList,
      customStatusList,
      sourceTypeList,
      tpaNumberList,
      filterGroupingOne,
      filterGroupingTwo,
      startPreparationLabel,
      customStartPreparationDate,
      truckDepartureLabel,
      customTruckDepartureDate,
      pickingStatusList,
    } = parameters;

    if (closedWKs)
      queryStrings.push(`closedWKs=${encodeURIComponent(closedWKs)}`);
    if (customer)
      queryStrings.push(`customerList=${encodeURIComponent(customer)}`);
    if (workCenter)
      queryStrings.push(`workCenterList=${encodeURIComponent(workCenter)}`);
    if (uap) queryStrings.push(`uapList=${encodeURIComponent(uap)}`);
    if (pickingOrder)
      queryStrings.push(`pickingOrder=${encodeURIComponent(pickingOrder)}`);
    if (outboundDelivery)
      queryStrings.push(`outboundList=${encodeURIComponent(outboundDelivery)}`);
    if (material)
      queryStrings.push(`materialList=${encodeURIComponent(material)}`);
    if (sourceTypeList)
      queryStrings.push(`sourceTypeList=${encodeURIComponent(sourceTypeList)}`);
    if (destinationTypeList)
      queryStrings.push(
        `destinationTypeList=${encodeURIComponent(destinationTypeList)}`,
      );
    if (pickingStatusList?.length) {
      for (const status of pickingStatusList) {
        queryStrings.push(`pickingStatusList[]=${encodeURIComponent(status)}`);
      }
    }
    if (customStatusList)
      queryStrings.push(
        `customStatusList=${encodeURIComponent(customStatusList)}`,
      );
    if (tpaNumberList)
      queryStrings.push(`tpaNumberList=${encodeURIComponent(tpaNumberList)}`);
    if (filterGroupingOne)
      queryStrings.push(
        `filterGroupingOne=${encodeURIComponent(filterGroupingOne)}`,
      );
    if (filterGroupingTwo)
      queryStrings.push(
        `filterGroupingTwo=${encodeURIComponent(filterGroupingTwo)}`,
      );
    if (startPreparationLabel !== undefined)
      queryStrings.push(
        `startPreparation=${encodeURIComponent(startPreparationLabel)}`,
      );
    if (customStartPreparationDate !== undefined)
      queryStrings.push(
        `startPreparationDate=${encodeURIComponent(customStartPreparationDate)}`,
      );
    if (truckDepartureLabel !== undefined)
      queryStrings.push(
        `truckDeparture=${encodeURIComponent(truckDepartureLabel)}`,
      );
    if (customTruckDepartureDate !== undefined)
      queryStrings.push(
        `truckDepartureDate=${encodeURIComponent(customTruckDepartureDate)}`,
      );

    return queryStrings.join('&');
  },

