import { defineStore } from 'pinia';
import { UserPreference } from '../modules/leveling-board/dto/userPreference';
import { FilterConfig } from '../modules/leveling-board/filter-config/dtos/filter-config.dto';
import {
  createFilterConfig,
  getFilterConfigByPlant,
  updateFilterConfig,
  getFilterByUserAndGroup,
} from '../modules/leveling-board/filter-config/services/api';

import * as api from '../modules/leveling-board/service/api';
import { useProfileStore } from './user-auth-store';

export const useFilterStore = defineStore('filterStore', {
  actions: {
    applyUserPreferences(preferences: Array<UserPreference | FilterConfig>) {
      for (const preference of preferences) {
        if (preference.userCriteria) {
          const criteria = preference.userCriteria.split(';');
          for (const criterion of criteria) {
            const [type, values] = criterion.split(':');
            const valueArray = values ? values.split(',') : [];
            switch (type) {
              case 'materials': {
                this.materialsSelected = valueArray;

                break;
              }
              case 'tpa': {
                this.tpaSelected = valueArray;
                break;
              }
              case 'picking-order': {
                this.pickingOrderSelected = valueArray;
                break;
              }
              case 'work-center': {
                this.workCentersSelected = valueArray.map((value) => {
                  const [id, label] = value.split('-');
                  const isParent = label.includes('parent');
                  return {
                    id: value,
                    label,
                    parentId: isParent ? undefined : id.slice(0, 6), // UAP part for parents, assuming format
                    level: isParent ? 0 : 1,
                  };
                });
                break;
              }
              case 'customer': {
                this.customersSelected = valueArray;
                break;
              }
              case 'srcLoc': {
                this.srcTypSelected = valueArray;
                break;
              }
              case 'destLoc': {
                this.destTypSelected = valueArray;
                break;
              }
              case 'custom-status': {
                this.custStatusSelected = valueArray;
                break;
              }
              case 'picking-status': {
                this.pickingStatusSelected = valueArray;
                break;
              }
              case 'outbound-del': {
                this.outboundDeliverySelected = valueArray;
                break;
              }
              // Apply the selected date from preferences
              case 'date': {
                this.selectedDate =
                  values === 'CustomDateRange' ? 'CurrentDay' : values;
                break;
              }
              case 'flow': {
                this.flow = values === '1';
                break;
              }
              case 'alert': {
                this.alert = values === '1';
                break;
              }
              case 'pikStatus': {
                this.pikStatus = values === '1';
                break;
              }
              case 'closedWKs': {
                this.closedWKs = values !== '0';
                break;
              }
              case 'start-preparation-type': {
                this.startPreparationType = values;
                break;
              }
              case 'start-preparation-time': {
                this.startPreparationTime = values;
                break;
              }
              case 'truck-departure-type': {
                this.truckDepartureType = values;
                break;
              }
              case 'truck-departure-time': {
                this.truckDepartureDate = values;
                break;
              }
              default: {
                break;
              }
            }
          }
        }
      }
    },
    async fetchUserPreferences(
      groupName?: string,
    ): Promise<Array<UserPreference | FilterConfig>> {
      const userProfile = useProfileStore();
      const { plant } = userProfile.userAttributes;
      const userId = localStorage.getItem('userId') || 'undefined';

      try {
        if (!groupName) {
          const preferences: Array<UserPreference> =
            await api.fetchUserPreferenceByPlantUserIdAndAppName(
              Number(plant),
              Number(userId),
              'LEVELING-BOARD',
            );
          this.applyUserPreferences(preferences);
          return preferences;
        }
        const groupPreference: FilterConfig | null =
          await getFilterByUserAndGroup(plant, groupName, 'LEVELING-BOARD');
        this.selectedDropdownGroup = groupPreference.groupName;
        const preferences: Array<FilterConfig> = [groupPreference];
        this.applyUserPreferences(preferences);
        return preferences;
      } catch (error) {
        console.error('Error fetching preferences:', error);
        return [];
      }
    },
    formatUserCriteria(): string {
      const filterTypes = [
        { type: 'materials', values: this.materialsSelected },
        { type: 'tpa', values: this.tpaSelected },
        {
          type: 'picking-order',
          values: this.pickingOrderSelected ? [this.pickingOrderSelected] : [],
        },
        {
          type: 'work-center',
          values: this.workCentersSelected,
        },
        { type: 'customer', values: this.customersSelected },
        { type: 'srcLoc', values: this.srcTypSelected },
        { type: 'destLoc', values: this.destTypSelected },
        { type: 'custom-status', values: this.custStatusSelected },
        { type: 'picking-status', values: this.pickingStatusSelected },
        { type: 'outbound-del', values: this.outboundDeliverySelected },
      ];

      const toggleCriteria = [
        { type: 'flow', value: this.flow },
        { type: 'alert', value: this.alert },
        { type: 'pikStatus', value: this.pikStatus },
        { type: 'closedWKs', value: this.closedWKs },
      ].map((toggle) => `${toggle.type}:${toggle.value ? '1' : '0'}`);

      return [
        ...filterTypes
          .map((filter) => {
            if (filter.type === 'work-center') {
              const values = Array.isArray(filter.values)
                ? filter.values
                    .map((v) =>
                      typeof v === 'object' && 'id' in v ? v.id : '',
                    )
                    .filter((id) => !!id)
                : [];
              return values.length > 0
                ? `${filter.type}:${values.join(',')}`
                : '';
            }

            const values = Array.isArray(filter.values)
              ? filter.values.map(String)
              : [];
            return values.length > 0
              ? `${filter.type}:${values.join(',')}`
              : '';
          })
          .filter((criteria) => criteria !== ''),
        ...toggleCriteria,
        ...(this.selectedDate ? [`date:${this.selectedDate}`] : []),
        ...(this.startPreparationType
          ? [`start-preparation-type:${this.startPreparationType}`]
          : []),
        ...(this.startPreparationTime
          ? [`start-preparation-time:${this.startPreparationTime}`]
          : []),
        ...(this.truckDepartureType
          ? [`truck-departure-type:${this.truckDepartureType}`]
          : []),
        ...(this.truckDepartureDate
          ? [`truck-departure-time:${this.truckDepartureDate}`]
          : []),
      ].join(';');
    },
    async saveFilterConfig(
      layoutName: string,
      groupName: string,
      plant: string,
      userCriteria: string,
      userId: number,
    ) {
      if (!groupName) {
        throw new Error('Layout name is required');
      }
      if (!userCriteria || Object.keys(userCriteria).length === 0) {
        throw new Error('At least one filter value must be selected');
      }

      const payload = {
        appName: layoutName,
        groupName,
        plant,
        userCriteria,
        userId,
      };
      return createFilterConfig(payload);
    },
    async saveFilterPreferences() {
      this.displayFilter = false;
      const userProfile = useProfileStore();
      const plant = Number(userProfile.userAttributes.plant);
      const userCriteria = this.formatUserCriteria();
      const userId = localStorage.getItem('userId') ?? 'undefined';
      const preferenceData: UserPreference = {
        action: 'FILTER',
        appName: 'LEVELING-BOARD',
        plant,
        user: { userId },
        userCriteria,
      };
      try {
        const result = await api.saveUserPreferences([preferenceData]);
        return result;
      } catch (error) {
        console.error('Error saving preferences:', error);
        throw error;
      }
    },

    async fetchFilterConfigByPlant(plant: string, appName: string) {
      try {
        const filterConfigs = await getFilterConfigByPlant(plant, appName);
        return filterConfigs;
      } catch (error) {
        console.error('Error fetching filter configs:', error);
        return [];
      }
    },

    async updateFilterConfig(id: number, data: FilterConfig) {
      try {
        const updated = await updateFilterConfig(id, data);
        return updated;
      } catch (error) {
        console.error('Error updating filter config:', error);
        throw error;
      }
    },
  },

  state: () => ({
    alert: true as boolean,
    closedWKs: false as boolean,
    custStatusList: [] as Array<string>,
    custStatusSelected: [] as Array<string>,
    customStartPreparationDate: '' as string,
    customTruckDepartureDate: '' as string,
    customerList: [] as Array<string>,
    customersSelected: [] as Array<string>,
    destTypList: [] as Array<string>,
    destTypSelected: [] as Array<string>,
    displayFilter: false,
    isDefault: true,
    selectedDropdownGroup: '' as string | null,
    flow: true as boolean,
    materialsList: [] as Array<string>,
    materialsSelected: [] as Array<string>,
    options: ['All', 'Past', 'Specific', 'Future'],
    outboundDeliveryList: [] as Array<string>,
    outboundDeliverySelected: [] as Array<string>,
    pickingOrder: '' as string,
    pickingOrderList: [] as Array<string>,
    pickingOrderSelected: [] as Array<string>,
    pickingStatus: '',
    pickingStatusList: ['IN PRODUCTION', 'CLOSED', 'TAKE FROM POOL'],
    pickingStatusSelected: [] as Array<string>,
    pikStatus: true as boolean,
    preReschedule: true as boolean,
    selectedDate: 'CurrentDay' as string, // Default to 'Current Day'
    shopOrderSelected: [] as Array<string>,
    showPopup: false,
    sourceTypList: [] as Array<string>,
    srcTypSelected: [] as Array<string>,
    startPreparationLabel: 'ALL' as string,
    startPreparationTime: '',
    startPreparationType: '',
    tpaList: [] as Array<string>,
    tpaSelected: [] as Array<string>,
    truckDepartureDate: '',
    truckDepartureLabel: 'ALL' as string,
    truckDepartureType: '',
    workCentersSelected: [] as Array<{
      id: string;
      label: string;
      parentId: string | undefined;
      level: number;
    }>,
    workcenterList: [] as Array<{ wcCode: string; wcDesc: string }>,
  }),
});

